export function mediaNotes(kind){return kind==='cassette'?[[261.63,329.63,392,493.88],'triangle']:kind==='record'?[[220,277.18,329.63,440,554.37],'sine']:kind==='disc'?[[392,493.88,587.33,783.99],'sine']:kind==='jukebox'?[[196,246.94,293.66,392,493.88],'square']:[[174.61,220,261.63,349.23],'triangle'];}
